const item = $input.first().json;
const html = item.body || item.data || item.html || Object.values(item).find(v => typeof v === 'string' && v.length > 100) || '';
const base = 'https://trysoftai.com';

if (!html) {
  throw new Error('No HTML received from homepage');
}

const matches = [...html.matchAll(/href=["']([^"'#\s]+)["']/gi)];
const allLinks = matches.map(m => m[1]);

const internal = [...new Set(
  allLinks
    .filter(l => l && l.trim() !== '')
    .filter(l => l.startsWith('/') || l.startsWith(base))
    .filter(l => !l.includes('facebook'))
    .filter(l => !l.includes('twitter'))
    .filter(l => !l.includes('linkedin'))
    .filter(l => !l.includes('instagram'))
    .filter(l => !l.includes('youtube'))
    .filter(l => !l.includes('.css'))
    .filter(l => !l.includes('.js'))
    .filter(l => !l.includes('.png'))
    .filter(l => !l.includes('.jpg'))
    .filter(l => !l.includes('.jpeg'))
    .filter(l => !l.includes('.gif'))
    .filter(l => !l.includes('.svg'))
    .filter(l => !l.includes('.webp'))
    .filter(l => !l.includes('.ico'))
    .filter(l => !l.includes('.woff'))
    .filter(l => !l.includes('.ttf'))
    .filter(l => !l.includes('.pdf'))
    .filter(l => !l.includes('/wp-content/'))
    .filter(l => !l.includes('/wp-includes/'))
    .filter(l => !l.includes('/wp-json/'))
    .filter(l => !l.includes('/wp-admin/'))
    .filter(l => !l.includes('?ver='))
    .filter(l => !l.includes('cache/min'))
    .filter(l => !l.includes('/feed/'))
    .filter(l => !l.includes('/xmlrpc'))
    .filter(l => !l.includes('/tag/'))
    .filter(l => !l.includes('/category/'))
    .filter(l => !l.includes('/page/'))
    .filter(l => !l.startsWith('#'))
    .filter(l => !l.match(/\/\d{4}\/\d{2}\//)) 
    .filter(l => !l.includes('/author/'))
    .filter(l => !l.includes('//fonts.googleapis'))
    .filter(l => !l.includes('//www.googletagmanager'))
    .filter(l => !l.includes('//maps.google'))
    .map(l => {
      let url = l.startsWith('/') ? base + l : l;
      // Remove query strings and fragments
      url = url.split('?')[0].split('#')[0];
      // Ensure trailing slash consistency
      return url;
    })
    .filter(l => l.startsWith(base))
    .filter(l => l.length > base.length) // Remove bare base URL duplicates... keep homepage explicitly
)];

// Always include homepage
const finalUrls = [base + '/', ...internal.filter(u => u !== base + '/')];
const unique = [...new Set(finalUrls)];

console.log('Total REAL pages found:', unique.length);
console.log('URLs:', JSON.stringify(unique, null, 2));

return unique.map(url => ({ json: { pageUrl: url } }));

// Preserve the pageUrl before Wait node resets context
const url = $input.first().json.pageUrl;
if (!url) {
  throw new Error('pageUrl is missing from input');
}
console.log('Processing URL:', url);
return [{ json: { pageUrl: url } }];

const item = $input.first().json;

// Get HTML
const html = item.body || item.data || item.html || item.content ||
  Object.values(item).find(v => typeof v === 'string' && v.length > 200) || '';

// Get URL - check previous nodes context
const url = item.pageUrl || item.url || $('Preserve URL').first().json.pageUrl || 'Unknown URL';

if (!html || html.length < 100) {
  console.log('No content for:', url);
  return [{ json: { 
    url, 
    content: `=== PAGE: ${url} ===\nNo content found\n================================\n`,
    charCount: 0
  }}];
}

// Deep HTML cleaning
const clean = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<footer[\s\S]*?<\/footer>/gi, '')
  .replace(/<header[\s\S]*?<\/header>/gi, '')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, '')
  .replace(/<iframe[\s\S]*?<\/iframe>/gi, '')
  .replace(/<svg[\s\S]*?<\/svg>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/&amp;/g, '&')
  .replace(/&nbsp;/g, ' ')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#038;/g, '&')
  .replace(/&#8217;/g, "'")
  .replace(/&#8216;/g, "'")
  .replace(/&#8220;/g, '"')
  .replace(/&#8221;/g, '"')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const content = `=== PAGE: ${url} ===\n${clean}\n================================\n`;

console.log(`Scraped: ${url} | Characters: ${clean.length}`);

return [{ json: { url, content, charCount: clean.length } }];

const data = $input.first().json.allPages;

if (!data || !Array.isArray(data)) {
  throw new Error('No pages data received from Aggregate node');
}

// Combine all page content
const allContent = data
  .filter(p => p.content && p.charCount > 0)
  .map(p => p.content)
  .join('\n\n');

// Build summary
const totalPages = data.length;
const successPages = data.filter(p => p.charCount > 0).length;
const failedPages = data.filter(p => p.charCount === 0).map(p => p.url);

const summary = `
========================================
WEBSITE SCRAPING REPORT
========================================
Website: https://trysoftai.com
Scraped At: ${new Date().toISOString()}
Total Pages Found: ${totalPages}
Successfully Scraped: ${successPages}
Failed Pages: ${failedPages.length > 0 ? failedPages.join(', ') : 'None'}
========================================

`;

const finalDocument = summary + allContent;

console.log('Final document length:', finalDocument.length);
console.log('Total pages scraped:', successPages);

return [{ 
  json: { 
    websiteData: finalDocument,
    totalPages,
    successPages,
    failedPages,
    scrapedAt: new Date().toISOString(),
    documentLength: finalDocument.length
  } 
}];

// Get the website data from previous node
const data = $input.first().json.websiteData || 
             $input.first().json.content ||
             Object.values($input.first().json).find(v => typeof v === 'string' && v.length > 100);

if (!data) {
  throw new Error('No website data found in input');
}

// Google Docs has a 1MB limit per request
// So we trim if too long
const trimmed = data.substring(0, 800000);

return [{ json: { textToInsert: trimmed } }];
